svg.script:
//
const NABU_RULES = {
    "prefixReplacement": {
        "global": {
            "arg:": { "replacement": "argument:" },
            "esc:": { "replacement": "escape:" },
            "sink:": { "replacement": "sink:" },
            "source:": { "replacement": "source:" },
            "opt\\b": { "replacement": "optionally" },
            "rpt\\b": { "replacement": "repeated" },
            "alt\\s*#?\\s*(\\d+)\\s*/\\s*(\\d+)": { "replacement": "alternative number $1 out of $2" },
            "\\*\\s*(\\d+)": { "replacement": "occurs $1 times" },
            "\\*": { "replacement": "occurs multiple times" }
        }
    },
    "nameAdornment": {
        "Requirement Ladder": {
            "dashedArc": {
                "prefix": "returns ",
                "postfix": "",
                "regex": "^(?!.*esc:)(?!.*escape)(?!.*sink:)(?!.*source:)(.*)$"
            },
            "requiresNonGraphviz": {
                "regex": "^to\\s+",
                "replacement": "requires to "
            },
            "requiresGraphvizEdge": {
                "regex": "^(?!.*requires)(?!.*to\\s+)(?!.*escape)(.*)$",
                "replacement": "requires $1"
            },
            "escapeArc": {
                "prefix": "escape ",
                "postfix": ""
            },
            "foreignTraversal": {
                "regex": "to\\s*\\([^\\)]*\\)",
                "replacement": "Foreign traversal hidden"
            }
        },
        "Requirement Tree": {
            "requiresNonGraphviz": {
                "regex": "^to\\s+",
                "replacement": "requires to "
            },
            "requiresGraphvizEdge": {
                "regex": "^(?!.*requires)(?!.*to\\s+)(?!.*escape)(.*)$",
                "replacement": "requires $1"
            },
            "backwardArc": {
                "prefix": "back and requires ",
                "postfix": ""
            },
            "escapeArc": {
                "prefix": "escape ",
                "postfix": ""
            },
            "foreignTraversal": {
                "regex": "to\\s*\\([^\\)]*\\)",
                "replacement": "Foreign traversal hidden"
            }
        },
        "Breakdown Diagram": {
            "requiresNonGraphviz": {
                "regex": "^to\\s+",
                "replacement": "requires to "
            }
        },
        "Coupling Chart": {
            "rightCoupling": {
                "prefix": "coupled by ",
                "postfix": ", with:"
            },
            "leftCoupling": {
                "prefix": "requires ",
                "postfix": ""
            },
            "ellipsis": {
                "regex": "(?:\\(|\\s|^)\\.\\.\\.(?:\\)|\\s|$)",
                "replacement": "No couplings inside"
            }
        }
    }
};

function toggle(el, isAnimating) {
    var triggerGroup = el.closest('g');
    var childrenGroups = [];

    // Climb DOM tree until we locate the adjacent content groups
    while (triggerGroup && triggerGroup.tagName === 'g') {
        var sibling = triggerGroup.nextElementSibling;
        var foundAny = false;
        while (sibling) {
            if (sibling.tagName === 'g') {
                childrenGroups.push(sibling);
                foundAny = true;
            }
            sibling = sibling.nextElementSibling;
        }
        // If we found sibling groups, stop climbing.
        if (foundAny) break;
        // Otherwise, if we are trapped in an inner wrapper, climb out.
        triggerGroup = triggerGroup.parentElement;
        if (triggerGroup && triggerGroup.id) {
            break; // Stop at major structural graph IDs
        }
    }

    var hasChildrenGroup = (childrenGroups.length > 0);
    var isHiding = false;

    if (hasChildrenGroup) {
        isHiding = (childrenGroups[0].style.display !== 'none');
    } else {
        isHiding = (el.textContent === '-');
    }

    var newDisplay = isHiding ? 'none' : 'inline';
    var newText = isHiding ? '+' : '-';

    if (hasChildrenGroup) {
        childrenGroups.forEach(function (group) {
            if (isHiding) {
                var nestedTriggers = group.querySelectorAll('.collapsible-trigger');
                nestedTriggers.forEach(function (trigger) {
                    if (trigger.textContent === '-') {
                        toggle(trigger, isAnimating);
                    }
                });
            }
            group.style.display = newDisplay;
        });
    }

    el.textContent = newText;

    var targetsStr = el.getAttribute('data-targets');
    if (targetsStr) {
        var targetIds = targetsStr.split(',');
        targetIds.forEach(function (id) {
            var target = document.getElementById(id);
            if (target) {
                var count = parseInt(target.getAttribute('data-ref-count') || '1');
                count += (isHiding ? -1 : 1);
                target.setAttribute('data-ref-count', count);

                if (!isAnimating && !isHiding) {
                    target.style.display = (count > 0) ? 'inline' : 'none';
                } else if (!isAnimating && isHiding) {
                    target.style.display = (count > 0) ? 'inline' : 'none';
                }
            }
        });
    }
}

var animationInterval = 4000;
var animationTimer = null;
var animatedNodes = [];
var animatedNodeData = []; // Pre-extracted node text and metadata
var currentAnimationIndex = -1;
var currentAnimationSequenceId = 0;
var isAnimationActive = false;
var baselineDisplayStates = []; // to store baseline visibility

// Speech-sequence guard state (robust platform-bug bypass)
var nabuLatestSpeechSequenceId = -1;
var nabuLatestSpeechToken = 0;
var nabuAnimationBlocked = false;
var nabuActiveSpeechUtterance = null;

// Event listeners for Window SAPI cleanup have been intentionally disabled,
// as `cancel()` causes a fatal lockup on Windows 11 Chrome/Edge audio drivers.
// Ensuring natural drain is required.

// Ensure speech acts natively.
document.addEventListener('change', function (e) {
    if (e.target && e.target.id === 'animSpeech' && !e.target.checked) {
        if (window.speechSynthesis) {
            setTimeout(function () {
                if (window.speechSynthesis.speaking || window.speechSynthesis.pending) {
                    try { window.speechSynthesis.cancel(); } catch (err) {}
                }
            }, 100);
        }
    }
});

function highlightNode(nodeGroup, highlight) {
    if (!nodeGroup) return;

    var targetTexts = [];
    var trigger = Array.from(nodeGroup.querySelectorAll('.collapsible-trigger')).find(function (t) {
        return t.closest('.collapsible-group') === nodeGroup;
    });
    var isGraphviz = nodeGroup.classList.contains('node') || nodeGroup.classList.contains('edge') || nodeGroup.querySelector('.node') !== null || nodeGroup.querySelector('.edge') !== null;

    function markFallbackShape(activate) {
        var shape = nodeGroup.querySelector('rect, polygon, polyline, path, circle, ellipse');
        if (!shape) return;
        if (activate) {
            if (!shape.hasAttribute('data-orig-stroke')) {
                shape.setAttribute('data-orig-stroke', shape.getAttribute('stroke') || 'none');
                shape.setAttribute('data-orig-stroke-width', shape.getAttribute('stroke-width') || '');
            }
            shape.setAttribute('stroke', 'Magenta');
            shape.setAttribute('stroke-width', '3');
        } else {
            if (shape.hasAttribute('data-orig-stroke')) {
                var os = shape.getAttribute('data-orig-stroke');
                if (os && os !== 'none') shape.setAttribute('stroke', os);
                else shape.removeAttribute('stroke');
                shape.removeAttribute('data-orig-stroke');
            } else {
                shape.removeAttribute('stroke');
            }
            if (shape.hasAttribute('data-orig-stroke-width')) {
                var ow = shape.getAttribute('data-orig-stroke-width');
                if (ow) shape.setAttribute('stroke-width', ow);
                else shape.removeAttribute('stroke-width');
                shape.removeAttribute('data-orig-stroke-width');
            } else {
                shape.removeAttribute('stroke-width');
            }
        }
    }

    if (isGraphviz) {
        // Support for Graphviz SVG structures (nested <g class="node"> contains multiple <text> tags)
        targetTexts = Array.from(nodeGroup.querySelectorAll('text')).filter(function (t) {
            return !t.classList.contains('collapsible-trigger') && !t.classList.contains('visually-hidden');
        });
    } else {
        var directTexts = Array.from(nodeGroup.querySelectorAll('text')).filter(function (t) {
            return t.closest('.collapsible-group') === nodeGroup && !t.classList.contains('collapsible-trigger') && !t.classList.contains('visually-hidden') && !t.closest('.descriptor-cells');
        });

        targetTexts = targetTexts.concat(directTexts);

        var isArc = isGraphviz || nodeGroup.querySelector('line') || nodeGroup.querySelector('path') || nodeGroup.querySelector('polygon') || nodeGroup.querySelector('polyline');

        // Only absorb securely adjacent preceding singleton text/descriptors
        var prev = nodeGroup.previousElementSibling;
        if (targetTexts.length === 0 && prev) {
            if ((prev.tagName === 'g' || prev.tagName === 'G') && prev.classList.contains('descriptor-cells')) {
                var texts = prev.querySelectorAll('text');
                if (texts.length > 0) targetTexts = targetTexts.concat(Array.from(texts));
            } else if (prev.tagName === 'text' || prev.tagName === 'TEXT') {
                targetTexts.push(prev);
            }
            if (targetTexts.length === 0 && isArc) {
                while (prev && prev.tagName !== 'g' && prev.tagName !== 'G') {
                    if (prev.tagName === 'text' || prev.tagName === 'TEXT') {
                        targetTexts.unshift(prev);
                    }
                    prev = prev.previousElementSibling;
                }
            }
        }
    }

    if (highlight) {
        if (targetTexts.length > 0) {
            targetTexts.forEach(function (targetText) {
                targetText.classList.add('highlighted-node');
                targetText.style.fill = "Maroon";
                if (!targetText.hasAttribute('data-orig-font-weight')) {
                    targetText.setAttribute('data-orig-font-weight', targetText.getAttribute('font-weight') || '');
                }
                targetText.setAttribute("font-weight", "bold");
                var bbox = targetText.getBBox();
                if (bbox.width > 0 && bbox.height > 0) {
                    var bgRect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
                    bgRect.setAttribute("class", "highlight-bg");
                    bgRect.setAttribute("x", bbox.x - 2);
                    bgRect.setAttribute("y", bbox.y - 2);
                    bgRect.setAttribute("width", bbox.width + 4);
                    bgRect.setAttribute("height", bbox.height + 4);
                    bgRect.setAttribute("fill", "lemonchiffon");
                    bgRect.setAttribute("rx", "2");
                    // Insert behind the text node
                    targetText.parentNode.insertBefore(bgRect, targetText);
                }
            });

            if (targetTexts[0].scrollIntoView) {
                var isArc = isGraphviz || nodeGroup.querySelector('line') || nodeGroup.querySelector('path') || nodeGroup.querySelector('polygon') || nodeGroup.querySelector('polyline');
                var nodeToScroll = (isArc) ? targetTexts[targetTexts.length - 1] : targetTexts[0];
                nodeToScroll.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'center' });
            }
        } else {
            // Apply graphical outline emphasis to native ellipsis/empty boxes that natively possess no text
            var isEdge = isGraphviz && (nodeGroup.classList.contains('edge') || nodeGroup.querySelector('.edge'));
            if (!isEdge) {
                markFallbackShape(true);
            }
        }
        if (isGraphviz && (nodeGroup.classList.contains('edge') || nodeGroup.querySelector('.edge'))) {
            nodeGroup.querySelectorAll('path, polygon').forEach(function (p) {
                if (!p.hasAttribute('data-orig-stroke')) {
                    p.setAttribute('data-orig-stroke', p.getAttribute('stroke') || '');
                }
                if (!p.hasAttribute('data-orig-stroke-width')) {
                    p.setAttribute('data-orig-stroke-width', p.getAttribute('stroke-width') || '');
                }
                p.setAttribute('stroke', 'Maroon');
                p.setAttribute('stroke-width', '3');
            });
        }
    } else {
        if (targetTexts.length > 0) {
            targetTexts.forEach(function (targetText) {
                targetText.classList.remove('highlighted-node');
                targetText.style.fill = "";
                if (targetText.hasAttribute('data-orig-font-weight')) {
                    var ofw = targetText.getAttribute('data-orig-font-weight');
                    if (ofw) targetText.setAttribute('font-weight', ofw);
                    else targetText.removeAttribute('font-weight');
                } else {
                    targetText.removeAttribute("font-weight");
                }

                // Securely scrub ANY background highlight rectangles injected prior globally relative to this node
                var pNode = targetText.parentNode;
                if (pNode) {
                    var bgs = pNode.querySelectorAll(':scope > .highlight-bg');
                    bgs.forEach(function (bg) {
                        try { bg.parentNode.removeChild(bg); } catch (e) { }
                    });
                }
            });
        } else {
            // Fallback highlight for nodes without text.
            if (!highlight) {
                var isEdge = isGraphviz && (nodeGroup.classList.contains('edge') || nodeGroup.querySelector('.edge'));
                if (!isEdge) {
                    markFallbackShape(false);
                }
            }
        }
        if (isGraphviz && (nodeGroup.classList.contains('edge') || nodeGroup.querySelector('.edge'))) {
            nodeGroup.querySelectorAll('path, polygon').forEach(function (p) {
                if (p.hasAttribute('data-orig-stroke')) {
                    var os = p.getAttribute('data-orig-stroke');
                    if (os) p.setAttribute('stroke', os);
                    else p.removeAttribute('stroke');
                    p.removeAttribute('data-orig-stroke');
                } else {
                    p.removeAttribute('stroke');
                }
                if (p.hasAttribute('data-orig-stroke-width')) {
                    var ow = p.getAttribute('data-orig-stroke-width');
                    if (ow) p.setAttribute('stroke-width', ow);
                    else p.removeAttribute('stroke-width');
                    p.removeAttribute('data-orig-stroke-width');
                } else {
                    p.removeAttribute('stroke-width');
                }
            });
        }
    }
}

function speakNodeText(nodeGroup) {

    var isAssoc = (typeof window.NABU_VISUAL_NAME !== 'undefined' && window.NABU_VISUAL_NAME && window.NABU_VISUAL_NAME.indexOf('Association') !== -1);
    
    if (isAssoc) {
        var gNode = nodeGroup.classList.contains('node') ? nodeGroup : nodeGroup.querySelector('.node');
        if (gNode && !nodeGroup.classList.contains('edge') && !nodeGroup.querySelector('.edge')) {
            var titleEl = gNode.querySelector('title');
            if (titleEl) return titleEl.textContent.trim().replace(/\\n/g, ' ');
        }
    }

    var isGraphviz = nodeGroup.classList.contains('node') || nodeGroup.classList.contains('edge') || nodeGroup.querySelector('.node') !== null || nodeGroup.querySelector('.edge') !== null;
    var targetTexts = [];
    if (isGraphviz) {
        targetTexts = Array.from(nodeGroup.querySelectorAll('text')).filter(function (t) {
            return !t.classList.contains('collapsible-trigger');
        });
    } else {
        var directTexts = Array.from(nodeGroup.querySelectorAll('text')).filter(function (t) {
            return t.closest('.collapsible-group') === nodeGroup && !t.classList.contains('collapsible-trigger') && !t.closest('.descriptor-cells');
        });

        targetTexts = targetTexts.concat(directTexts);

        var isArc = isGraphviz || nodeGroup.querySelector('line') || nodeGroup.querySelector('path') || nodeGroup.querySelector('polygon') || nodeGroup.querySelector('polyline');

        var prev = nodeGroup.previousElementSibling;
        if (targetTexts.length === 0 && prev) {
            if ((prev.tagName === 'g' || prev.tagName === 'G') && prev.classList.contains('descriptor-cells')) {
                var texts = prev.querySelectorAll('text');
                if (texts.length > 0) targetTexts = targetTexts.concat(Array.from(texts));
            } else if (prev.tagName === 'text' || prev.tagName === 'TEXT') {
                targetTexts.push(prev);
            }
            if (targetTexts.length === 0 && isArc) {
                while (prev && prev.tagName !== 'g' && prev.tagName !== 'G') {
                    if (prev.tagName === 'text' || prev.tagName === 'TEXT') {
                        targetTexts.unshift(prev);
                    }
                    prev = prev.previousElementSibling;
                }
            }
        }
    }

    var joinStr = ' ';
    var isInjectedRequires = false;
    var txt = targetTexts.filter(function (domNode) {
        return true;
    }).map(function (t) {
        var tspans = Array.from(t.querySelectorAll('tspan'));
        if (tspans.length > 0) {
            return tspans.map(function (span) { return span.textContent.trim(); })
                .filter(function (s) { return s.length > 0 && s.indexOf('|') === -1 && s.indexOf('<') === -1; })
                .join(' ');
        }
        return t.textContent.trim();
    }).filter(function (t) {
        var isAssoc = (typeof window.NABU_VISUAL_NAME !== 'undefined' && window.NABU_VISUAL_NAME && window.NABU_VISUAL_NAME.indexOf('Association') !== -1);
        if (isAssoc && (t.match(/port_/i) || t.match(/^:/) || t.match(/:\s*port/i))) return false;
        return t.length > 0 && t.indexOf('|{') === -1 && t.indexOf('}|') === -1 && t !== '{' && t !== '}' && t !== '-';
    }).join(joinStr);

    // Use the JSON-based table manager (NABU_RULES) to process text formatting
    if (typeof NABU_RULES !== 'undefined') {
        var defaultVisual = (typeof window.NABU_VISUAL_NAME !== 'undefined' && window.NABU_VISUAL_NAME) ? window.NABU_VISUAL_NAME : (window.location ? window.location.href : '');

        
        var evalRule = function (t, r) {
            if (r.replacement != null && r.regex) {
                return t.replace(new RegExp(r.regex, 'ig'), r.replacement);
            } else if (r.prefix != null || r.postfix != null) {
                if (!r.regex || t.match(new RegExp(r.regex, 'i'))) {
                    return (r.prefix || "") + t + (r.postfix || "");
                }
            } else if (r.regex) {
                return t.replace(new RegExp(r.regex, 'ig'), "");
            }
            return t;
        };

        if (NABU_RULES.nameAdornment) {
            var visualKey = Object.keys(NABU_RULES.nameAdornment).find(k => defaultVisual.indexOf(k) !== -1);
            if (visualKey) {
                var rulesMap = NABU_RULES.nameAdornment[visualKey];
                
                // Strip redundant 'and ' prefix added by genericRequirementLadder for legacy narrative reasons before conditionals
                txt = txt.replace(/^and\s+(alt|opt|rpt|arg|pre|post|test|imp|ret|in scenario|substitute|sink|source)/i, '$1');

                // Extract structural prefixes before evaluating structural regexes
                var structuralRegex = /^(?:in scenario:\s*"[^"]*"\s*|substitute:\s*)?(?:(?:alt|opt|rpt|arg|pre|post|test|imp|ret|sink|source)[^:]*:\s*)*(?:\[\d+[a-z]{2}\]\s*)?/i;
                var structMatch = txt.match(structuralRegex);
                var extractedPrefix = "";
                if (structMatch && structMatch[0].length > 0) {
                    extractedPrefix = structMatch[0];
                    txt = txt.substring(extractedPrefix.length);
                }

                var eventTypesToCheck = ['foreignTraversal', 'ellipsis'];

                var poly = nodeGroup.querySelector('polygon') || nodeGroup.querySelector('polyline');
                var dashed = Array.from(nodeGroup.querySelectorAll('line[stroke-dasharray], path[stroke-dasharray], polygon[stroke-dasharray], polyline[stroke-dasharray]')).find(d => d.closest('.collapsible-group') === nodeGroup);
                if (!dashed && poly) {
                    var pg = poly.closest('g');
                    if (pg) dashed = Array.from(pg.querySelectorAll('[stroke-dasharray]')).find(d => d.closest('.collapsible-group') === nodeGroup);
                }
                var isDashed = dashed && dashed.getAttribute('stroke-dasharray') !== 'none';
                
                var isEscape = false;
                if (isDashed) {
                    if (dashed.tagName === 'line' || dashed.tagName === 'path') {
                        // The lack of arrowhead markers implies an Escape dashed-line, not a Returned-value dashed-arc
                        if (!dashed.hasAttribute('marker-end') && !dashed.hasAttribute('marker-mid') && !dashed.hasAttribute('marker-start')) {
                            isEscape = true;
                        }
                    }
                }

                if (isEscape) {
                    eventTypesToCheck.push('escapeArc');
                } else if (isDashed) {
                    eventTypesToCheck.push('dashedArc');
                }

                var isBackwardArc = false;
                var isReflexive = false;

                if (nodeGroup.classList.contains('edge')) {
                    var titleEl = nodeGroup.querySelector('title');
                    if (titleEl) {
                        var edgeTitleParts = titleEl.textContent.split('->');
                        if (edgeTitleParts.length === 2 && edgeTitleParts[0].trim() === edgeTitleParts[1].trim()) {
                            isReflexive = true;
                        }
                    }
                }

                if (!isReflexive) {
                    var ptsStr = poly ? poly.getAttribute('points') : null;
                    if (!ptsStr) {
                        var line = nodeGroup.querySelector('line[marker-end]') || nodeGroup.querySelector('path[marker-end]');
                        if (line && line.tagName === 'line') {
                            var x1 = parseFloat(line.getAttribute('x1')), x2 = parseFloat(line.getAttribute('x2'));
                            var y1 = parseFloat(line.getAttribute('y1')), y2 = parseFloat(line.getAttribute('y2'));
                            if (!isNaN(x1) && !isNaN(x2) && !isNaN(y1) && !isNaN(y2)) {
                                if ((x1 > x2 + 15) || (y1 > y2 + 15)) isBackwardArc = true;
                            }
                        }
                    } else if (ptsStr) {
                        var ptArr = ptsStr.split(/[\s,]+/);
                        var firstX = parseFloat(ptArr[0]), lastX = parseFloat(ptArr[ptArr.length - 2]);
                        var firstY = parseFloat(ptArr[1]), lastY = parseFloat(ptArr[ptArr.length - 1]);
                        if (!isNaN(firstX) && !isNaN(lastX) && !isNaN(firstY) && !isNaN(lastY)) {
                            if ((firstX > lastX + 15) || (firstY > lastY + 15)) isBackwardArc = true;
                        }

                        var box = nodeGroup.previousElementSibling;
                        while (box && box.tagName !== 'g' && !box.querySelector('rect')) box = box.previousElementSibling;
                        if (box) {
                            var r = box.querySelector('rect');
                            if (r) {
                                var rcx = parseFloat(r.getAttribute('x')) + (parseFloat(r.getAttribute('width')) / 2);
                                eventTypesToCheck.push((firstX > rcx) ? 'rightCoupling' : 'leftCoupling');
                            }
                        }
                    }
                }

                if (!isDashed && !txt.match(/returns/i) && isBackwardArc) {
                    eventTypesToCheck.push('backwardArc');
                }

                if (nodeGroup.classList.contains('edge') || nodeGroup.querySelector('.edge') !== null) {
                    eventTypesToCheck.push('requiresGraphvizEdge');
                } else {
                    eventTypesToCheck.push('requiresNonGraphviz');
                    eventTypesToCheck.push('requiresGraphvizNode');
                }

                eventTypesToCheck.forEach(function(evt) {
                    var rule = rulesMap[evt];
                    if (!rule) return;

                    if (evt === 'leftCoupling') {
                        var leftTxt = evalRule('', rule).trim();
                        if (leftTxt.length > 0) {
                            txt = leftTxt;
                            isInjectedRequires = false;
                        } else {
                            txt = "requires";
                            isInjectedRequires = true;
                        }
                    } else if (evt === 'rightCoupling') {
                        if (txt.length > 0) {
                            var newTxt = evalRule(txt, rule);
                            if (newTxt === txt) txt = "coupled by " + txt + " with";
                            else txt = newTxt;
                        }
                    } else if (evt === 'requiresGraphvizEdge') {
                        if (!txt.match(/requires/i) && !txt.match(/returns/i) && !txt.match(/to\s/i) && !txt.match(/No couplings inside/i) && txt.trim().length > 0) {
                            txt = evalRule(txt, rule);
                        }
                    } else if (evt === 'requiresNonGraphviz') {
                        if (txt.match(/(^|\s)to\s+/i)) {
                            txt = evalRule(txt, rule);
                        }
                    } else if (evt === 'dashedArc' || evt === 'backwardArc' || evt === 'foreignTraversal' || evt === 'ellipsis' || evt === 'escapeArc') {
                        if (txt.length > 0) txt = evalRule(txt, rule);
                    }
                });
                
                // Re-inject the structural prefix so it sits OUTSIDE the adorned phrasing
                txt = extractedPrefix + txt;
            }
        }

        if (NABU_RULES.prefixReplacement && NABU_RULES.prefixReplacement.global) {
            Object.keys(NABU_RULES.prefixReplacement.global).forEach(function(trigger) {
                var rule = NABU_RULES.prefixReplacement.global[trigger];
                var re = new RegExp('(?:^|\\s)' + trigger, 'ig');
                txt = txt.replace(re, ' ' + rule.replacement + ' ');
            });
        }
    }

    var finalText = txt.trim();
    if (finalText.toLowerCase() === 'requires' && isInjectedRequires) {
        try { nodeGroup.setAttribute('data-injected-requires', 'true'); } catch (e) {}
    } else {
        try { nodeGroup.removeAttribute('data-injected-requires'); } catch (e) {}
    }

    return finalText;
}

function expandAllNodes() {
    animatedNodes.forEach(function (node) {
        node.style.display = 'inline';
    });
    document.querySelectorAll('g.collapsible-group').forEach(function (g) {
        g.style.display = 'inline';
    });
    document.querySelectorAll('.collapsible-trigger').forEach(function (trigger) {
        trigger.textContent = '-';
        var g = trigger.closest('g');
        if (g && g.nextElementSibling && g.nextElementSibling.tagName === 'g') {
            g.nextElementSibling.style.display = 'inline';
        }
    });

    document.querySelectorAll('g.cluster').forEach(function (cluster) {
        cluster.style.display = 'inline';
