function showAnimationCancelPopup() {
    var popup = document.getElementById('nabu-animation-popup');
    if (!popup) {
        popup = document.createElement('div');
        popup.id = 'nabu-animation-popup';
        popup.style.position = 'fixed';
        popup.style.top = '20px';
        popup.style.left = '50%';
        popup.style.transform = 'translateX(-50%)';
        popup.style.backgroundColor = 'rgba(0, 0, 0, 0.8)';
        popup.style.color = 'white';
        popup.style.padding = '10px 20px';
        popup.style.borderRadius = '5px';
        popup.style.zIndex = '9999';
        popup.style.fontFamily = 'Arial, sans-serif';
        popup.style.fontSize = '14px';
        popup.style.boxShadow = '0 4px 6px rgba(0,0,0,0.3)';
        popup.style.display = 'flex';
        popup.style.alignItems = 'center';
        popup.style.gap = '15px';
        
        var text = document.createElement('span');
        text.innerText = 'Press <Escape> to cancel the animation';
        
        var btn = document.createElement('button');
        btn.innerText = 'Stop!';
        btn.style.backgroundColor = '#d9534f';
        btn.style.color = 'white';
        btn.style.border = 'none';
        btn.style.padding = '5px 10px';
        btn.style.borderRadius = '3px';
        btn.style.cursor = 'pointer';
        btn.style.fontWeight = 'bold';
        
        btn.onclick = function() {
            var animCheckbox = document.getElementById('animActive');
            if (animCheckbox) animCheckbox.checked = false;
            stopAnimation();
            popup.style.display = 'none';
        };
        
        popup.appendChild(text);
        popup.appendChild(btn);
        document.body.appendChild(popup);
    }
    popup.style.display = 'flex';
    
    setTimeout(function() {
        if (popup) popup.style.display = 'none';
    }, 5000);
}

function startAnimation(isAutoStart) {
