        };
    }

    animatedNodes = Array.from(document.querySelectorAll('g.collapsible-group')).filter(function (node) {
        var p = node.closest('div');
        if (p && p.style && p.style.display === 'none') return false;
        var shape = node.querySelector('rect, polyline, polygon, line, path, circle, ellipse, text');
        return shape && shape.closest('.collapsible-group') === node;
    });

    if (baselineDisplayStates.length === 0) {
        document.querySelectorAll('g.collapsible-group, g.cluster').forEach(function (g) {
            baselineDisplayStates.push({
                el: g,
                display: g.style.display || ''
            });
        });
    }

    // Automatic animation at page open
    if (animationInterval > 0 && animatedNodes.length > 0) {
        if (animCheckbox) animCheckbox.checked = true;
        animationTimer = setTimeout(function () {
            startAnimation(true);
        }, animationInterval);
    }
}

function setAnimationInterval(seconds) {
    var val = parseFloat(seconds);
    animationInterval = isNaN(val) ? 0 : val * 1000;

    var animCheckbox = document.getElementById('animActive');

    if (animationInterval <= 0) {
        if (animCheckbox) animCheckbox.checked = false;
        stopAnimation();
    } else {
        if (isAnimationActive) {
            // Already active, let it continue
        }
    }
}

document.addEventListener('DOMContentLoaded', function () {
    initAnimation();
});

document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && isAnimationActive) {
        var animCheckbox = document.getElementById('animActive');
        if (animCheckbox) animCheckbox.checked = false;
        stopAnimation();
        var popup = document.getElementById('nabu-animation-popup');
        if (popup) popup.style.display = 'none';
    }
});
